const workspaceOwnsTranscriptionJobManual = `-- name: WorkspaceOwnsTranscriptionJobManual :one
SELECT EXISTS(
  SELECT 1
  FROM transcription_jobs
  WHERE id = ?
    AND workspace_id = ?
) AS owns_job
`

type WorkspaceOwnsTranscriptionJobManualParams struct {
	JobID       uint64 `json:"job_id"`
	WorkspaceID uint64 `json:"workspace_id"`
}

func (q *Queries) WorkspaceOwnsTranscriptionJobManual(ctx context.Context, arg WorkspaceOwnsTranscriptionJobManualParams) (bool, error) {
	row := q.db.QueryRowContext(ctx, workspaceOwnsTranscriptionJobManual, arg.JobID, arg.WorkspaceID)
	var owns_job bool
	err := row.Scan(&owns_job)
	return owns_job, err
}
